#!/usr/bin/env bash
# Negative tests of infra/stack-tests/lint.py: every deliberately broken copy of the infra tree MUST make the linter fail.
# Run: bash infra/stack-tests/test_lint.sh
set -uo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; REPO="$(cd "$HERE/../.." && pwd)"
T_SUITE="lint"; . "$HERE/lib/t.sh"
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
fresh() { rm -rf "$TMP/w"; mkdir -p "$TMP/w/scripts"; for d in provision systemd backup release php mysql fail2ban logrotate stack-tests; do mkdir -p "$TMP/w/infra"; cp -R "$REPO/infra/$d" "$TMP/w/infra/$d"; done; cp -R "$REPO/scripts/ops" "$TMP/w/scripts/ops"; }
LINT() { AICC_LINT_INFRA="$TMP/w/infra" python3 "$REPO/infra/stack-tests/lint.py"; }
neg() { local out; out="$(LINT 2>&1)"; local rc=$?; if [ "$rc" != 0 ] && printf '%s' "$out" | grep -qF -- "$2"; then t_pass "$1"; else t_bad "$1" "rc=$rc, expected message '$2' in: $(printf '%s' "$out" | grep 'LINT FAIL' | head -3 | tr '\n' '|')"; fi; }
fresh; t_ok "the unmodified copy passes" LINT
fresh; sed -i.bak 's/^MemoryMax=450M/MemoryMaxx=450M/' "$TMP/w/infra/systemd/aicc-edge.service"; neg "a misspelled systemd key is caught" 'unknown/misplaced key MemoryMaxx'
fresh; sed -i.bak 's#^IPAddressDeny=.*#IPAddressDeny=169.254.0.0/16#' "$TMP/w/infra/systemd/overrides/php8.3-fpm.service.d/aicc.conf"; neg "an FPM drop-in that no longer denies the loopback is caught (review M1)" 'IPAddressDeny must cover'
fresh; sed -i.bak 's#^IPAddressAllow=.*#IPAddressAllow=127.0.0.1/32#' "$TMP/w/infra/systemd/aicc-wp-cron.service"; neg "allowing 127.0.0.1 for the cron user is caught" 'IPAddressAllow must be exactly the resolver stub'
fresh; sed -i.bak 's#TURNSTILE_HOST = "challenges.cloudflare.com"#TURNSTILE_HOST = "challenges.cloudflare.net"#' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "a wrong Turnstile verification host in the owner-facts renderer is caught (P32)" 'Turnstile verification host must be exactly'
fresh; sed -i.bak 's#facts.get("AICC_TURNSTILE_ENABLED") == "true"#True#' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "adding the Turnstile host without the explicit owner fact is caught (P32)" 'only by the explicit AICC_TURNSTILE_ENABLED=true'
fresh; sed -i.bak "s#'stage.copilt.org'#'stage.copilt.org,localhost,127.0.0.1'#" "$TMP/w/infra/provision/wp-config.stage.template.php"; neg "localhost / 127.0.0.1 back in WP_ACCESSIBLE_HOSTS is caught" 'WP_ACCESSIBLE_HOSTS must not contain localhost'
fresh; sed -i.bak 's#^ProtectSystem=strict#ProtectSystem=full#' "$TMP/w/infra/systemd/overrides/php8.3-fpm.service.d/20-aicc-sandbox.conf"; neg "a weakened FPM sandbox is caught" 'ProtectSystem=strict and NoNewPrivileges=yes required'
fresh; printf 'MemoryDenyWriteExecute=yes\n' >> "$TMP/w/infra/systemd/overrides/php8.3-fpm.service.d/20-aicc-sandbox.conf"; neg "MemoryDenyWriteExecute (breaks PCRE JIT) is caught" 'deliberately absent'
fresh; sed -i.bak 's/--confirm-production/--confirm-prod/g' "$TMP/w/infra/provision/render-wp-config.sh"; neg "render-wp-config.sh losing its production confirmation gate is caught" 'production gate lost'
fresh; sed -i.bak "s#define( 'WP_ACCESSIBLE_HOSTS', 'api.copilt.org' )#define( 'WP_ACCESSIBLE_HOSTS', 'api.copilt.org,stage.copilt.org' )#" "$TMP/w/infra/provision/wp-config.production.template.php"; neg "a production template whose allow-list is no longer exactly the API host is caught" 'WP_ACCESSIBLE_HOSTS exactly the API host'
fresh; printf '\n# uses wp-config.production.template.php\n' >> "$TMP/w/infra/provision/install-stack.sh"; neg "a script that starts using the production template is caught" 'references the production wp-config template'
fresh; sed -i.bak 's/never shipped in a release/shipped in a release/' "$TMP/w/infra/release/deploy-release.sh"; neg "deploy-release.sh losing its refusal of a wp-config template is caught" 'must refuse an artifact that carries a wp-config template'
fresh; sed -i.bak 's/^MemoryHigh=320M/MemoryHigh=200M/' "$TMP/w/infra/systemd/aicc-edge.service"; neg "Caddy MemoryHigh below its measured footprint is caught (review M-1)" 'MemoryHigh is below Caddy'
fresh; sed -i.bak 's/GOMEMLIMIT=256MiB/GOMEMLIMIT=400MiB/' "$TMP/w/infra/systemd/aicc-edge.service"; neg "GOMEMLIMIT above MemoryHigh is caught" 'GOMEMLIMIT must stay below MemoryHigh'
fresh; sed -i.bak 's#^ReadWritePaths=/srv/aicc/backups /var/lib/aicc/status#ReadWritePaths=/srv/aicc/backups /var/lib/aicc/nonexistent#' "$TMP/w/infra/systemd/aicc-backup.service"; neg "a ReadWritePaths directory the installer never creates is caught" 'installer does not create this directory'
fresh; sed -i.bak 's#^ExecStart=/usr/local/sbin/aicc-backup .*#ExecStart=/usr/local/sbin/aicc-backup-typo --label scheduled#' "$TMP/w/infra/systemd/aicc-backup.service"; neg "an ExecStart path that is not installed is caught" 'aicc-backup-typo'
fresh; sed -i.bak 's/^OnFailure=aicc-notify-failure@%n.service/OnFailure=nonexistent@%n.service/' "$TMP/w/infra/systemd/aicc-wp-cron.service"; neg "an OnFailure= template that does not exist is caught" 'template unit nonexistent@.service not found'
fresh; sed -i.bak 's/^After=network-online.target php8.3-fpm.service mysql.service/After=network-online.target/' "$TMP/w/infra/systemd/aicc-edge.service"; neg "losing the php-fpm ordering of aicc-edge is caught" 'must be After=php8.3-fpm.service'
fresh; sed -i.bak 's/^set -euo pipefail$/set -u/' "$TMP/w/infra/backup/aicc-backup.sh"; neg "a script without set -euo pipefail is caught" 'aicc-backup.sh: missing `set -euo pipefail`'
fresh; sed -i.bak 's/139\.59\.157\.231/0.0.0.0/g' "$TMP/w/infra/release/deploy-release.sh"; neg "a deploy script without the production IP deny list is caught" 'deploy-release.sh: production API IP'
fresh; echo 'DB_PASS="password: hunter2hunter2"' >> "$TMP/w/infra/provision/create-staging-db.sh"; sed -i.bak 's/password: hunter2hunter2/password = "hunter2hunter2"/' "$TMP/w/infra/provision/create-staging-db.sh"; neg "a literal password is caught" 'password with a value'
fresh; printf '%s\n' "# $(printf 'a%.0s' $(seq 1 3))$(openssl rand -hex 24)" >> "$TMP/w/infra/provision/install-stack.sh"; neg "an unexpected long hex string is caught" 'unexpected long hex string'
fresh; echo '# server 203.0.113.9 and 8.8.4.4' >> "$TMP/w/infra/provision/install-stack.sh"; neg "a public IPv4 literal is caught" 'public-looking IPv4 literal: 8.8.4.4'
fresh; sed -i.bak 's/^pm.max_children = 3/pm.max_children = 12/' "$TMP/w/infra/php/aicc-pool.conf"; neg "a pool that breaks the memory budget is caught" 'budget: PHP-FPM worst case exceeds'
fresh; sed -i.bak 's/dry-run/dryrun/g' "$TMP/w/infra/backup/pull-offhost.sh"; neg "a script without --dry-run is caught" 'pull-offhost.sh: no --dry-run option'
fresh; sed -i.bak 's/must run as root/must be someone/; s/id -u/id -g/g' "$TMP/w/infra/provision/harden-stage2.sh"; neg "a root-only script without the non-root refusal is caught" 'harden-stage2.sh: no non-root refusal'
fresh; python3 - "$TMP/w/infra/provision/wp-config.production.template.php" <<'PYEOF'
import sys
p = sys.argv[1]; t = open(p).read(); t = t.replace("// @@OWNER_FACTS_BEGIN@@\n", "").replace("// @@OWNER_FACTS_END@@\n", ""); open(p, "w").write(t)
PYEOF
neg "a production template that loses its owner-facts region markers is caught" 'exactly one owner-facts region'
fresh; sed -i.bak "s#^define( 'AICC_ENTITLEMENT_WEBHOOK_SECRET'#define( 'AICC_LEGAL_ENTITY_NAME', 'Hard Coded Ltd' );\ndefine( 'AICC_ENTITLEMENT_WEBHOOK_SECRET'#" "$TMP/w/infra/provision/wp-config.production.template.php"; neg "an owner fact defined in the template (it would hide an unset value) is caught" 'must not be defined in the template'
fresh; sed -i.bak 's/--owner-facts-file/--owner-facts/g' "$TMP/w/infra/provision/render-wp-config.sh"; neg "the renderer losing its owner-facts test seam / gate is caught" 'owner-facts gate lost'
fresh; echo 'echo x > "$OWNERF"' >> "$TMP/w/infra/provision/render-wp-config.sh"; neg "a renderer that writes the owner-facts file is caught" 'must never write the owner-facts file'
fresh; echo 'import subprocess' >> "$TMP/w/infra/provision/lib/owner_facts.py"; neg "an owner-facts validator that imports subprocess is caught" 'pure string handling'
fresh; sed -i.bak 's/aicc-owner-facts/aicc-owner-x/' "$TMP/w/infra/provision/install-stack.sh"; neg "an installer that no longer installs the owner-facts tool is caught" 'must install the owner-facts tool'
fresh; sed -i.bak 's/needs AICC_NOTIFY_ENABLED=true/needs notify/' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P37: losing the notification-switch refusal is caught" 'P37 rule lost: needs AICC_NOTIFY_ENABLED=true'
fresh; sed -i.bak 's/P37_APPROVED_CAPS = ("25", "50", "100")/P37_APPROVED_CAPS = ("25", "50", "100", "500")/' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P37: a self-service cap stage beyond 25/50/100 is caught" 'cap stages must be exactly 25, 50, 100'
fresh; sed -i.bak 's/"AICC_NOTIFY_ENABLED", "AICC_FUNNEL_COUNTERS_ENABLED", "AICC_OWNER_OPS_SECTION_ENABLED", "AICC_MILESTONE_SYNC_SCHEDULED",/"AICC_FUNNEL_COUNTERS_ENABLED", "AICC_OWNER_OPS_SECTION_ENABLED", "AICC_MILESTONE_SYNC_SCHEDULED",/' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P37: a switch that is no longer exactly-true is caught" 'P37 switch AICC_NOTIFY_ENABLED must be TRUE_ONLY'
fresh; sed -i.bak "s#^define( 'AICC_LM_PLUGIN_RELEASE_DIR'#define( 'AICC_TRIAL_SELF_SERVICE_ENABLED', true );\ndefine( 'AICC_LM_PLUGIN_RELEASE_DIR'#" "$TMP/w/infra/provision/wp-config.production.template.php"; neg "P37: a hard-coded self-service switch in the production template is caught" "AICC_TRIAL_SELF_SERVICE_ENABLED must not be defined in the template"
fresh; sed -i.bak "s#^// @@P37_END@@#// @@P37_END_X@@#" "$TMP/w/infra/provision/wp-config.production.template.php"; neg "P37: a malformed P37 region is caught" 'exactly one P37 region'
fresh; sed -i.bak 's#TURNSTILE_SECRET_FILE = "/etc/aicc-mail/turnstile.secret"#TURNSTILE_SECRET_FILE = "/etc/aicc/secrets/turnstile.secret"#' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P37: a secret file path PHP cannot traverse is caught" 'must be a fixed file under /etc/aicc-mail'
fresh; sed -i.bak 's/"AICC_LM_PAYMENT_GATE_STRICT", "AICC_EXTRA_ACCESSIBLE_HOSTS", "AICC_TURNSTILE_ENABLED"\],/"AICC_LM_PAYMENT_GATE_STRICT", "AICC_EXTRA_ACCESSIBLE_HOSTS", "AICC_TURNSTILE_ENABLED", "AICC_NOTIFY_ENABLED"],/' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P37: staging accepting a P37 fact is caught" 'staging must not accept any P37 owner fact'
fresh; sed -i.bak 's/a stage render may not carry the P37/a stage render may carry the P37/' "$TMP/w/infra/provision/render-wp-config.sh"; neg "P37: the renderer losing its staging refusal is caught" 'P37 gate lost: a stage render may not carry the P37'
fresh; sed -i.bak 's#BREVO_HOST = "api.brevo.com"#BREVO_HOST = "*.brevo.com"#' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P38: a wildcard Brevo host in the owner-facts renderer is caught" 'Brevo API host must be exactly api.brevo.com'
fresh; sed -i.bak 's#BREVO_KEY_FILE = "/etc/aicc-mail/brevo-api.key"#BREVO_KEY_FILE = "/etc/aicc/secrets/brevo-api.key"#' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P38: a key file path PHP cannot traverse is caught" 'must be the fixed /etc/aicc-mail/brevo-api.key'
fresh; sed -i.bak 's#MAIL_PROVIDERS = ("brevo_api", "smtp")#MAIL_PROVIDERS = ("brevo_api", "smtp", "ses")#' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P38: a third mail provider value is caught" 'accepts exactly brevo_api and smtp'
fresh; sed -i.bak 's#MAIL_FROM_DOMAINS = ("copilt.org",)#MAIL_FROM_DOMAINS = ("copilt.org", "example.com")#' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P38: a second sender domain is caught" 'sender domain is exactly copilt.org'
fresh; sed -i.bak 's#BREVO_DAY_CEILING = 300#BREVO_DAY_CEILING = 3000#' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P38: a Brevo daily ceiling above the Free plan is caught" 'Brevo Free daily ceiling is 300'
fresh; sed -i.bak 's/"AICC_PRIVACY_REQUESTS_ENABLED", "AICC_MAIL_STATUS_POLL_ENABLED")/"AICC_PRIVACY_REQUESTS_ENABLED")/' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P38: a status poll switch that is no longer exactly-true is caught" 'AICC_MAIL_STATUS_POLL_ENABLED must be TRUE_ONLY'
fresh; sed -i.bak 's/"AICC_MAIL_PROVIDER", "AICC_MAIL_FROM_ADDRESS",/"AICC_MAIL_PROVIDER", "AICC_MAIL_API_KEY", "AICC_MAIL_FROM_ADDRESS",/' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P38: an owner fact that carries the key is caught" 'no owner fact may carry or name the Brevo key'
fresh; sed -i.bak 's/"AICC_LM_PAYMENT_GATE_STRICT", "AICC_EXTRA_ACCESSIBLE_HOSTS", "AICC_TURNSTILE_ENABLED"\],/"AICC_LM_PAYMENT_GATE_STRICT", "AICC_EXTRA_ACCESSIBLE_HOSTS", "AICC_TURNSTILE_ENABLED", "AICC_MAIL_PROVIDER"],/' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P38: staging accepting a P38 fact is caught" 'staging must not accept any P38 owner fact'
fresh; sed -i.bak 's/both \/etc\/aicc-mail\/smtp.env and/two files and/' "$TMP/w/infra/provision/lib/owner_facts.py"; neg "P38: losing the both-secret-files refusal is caught" 'P38 rule lost: both /etc/aicc-mail/smtp.env and'
fresh; sed -i.bak "s#^define( 'AICC_LM_PLUGIN_RELEASE_DIR'#define( 'AICC_MAIL_PROVIDER', 'brevo_api' );\ndefine( 'AICC_LM_PLUGIN_RELEASE_DIR'#" "$TMP/w/infra/provision/wp-config.production.template.php"; neg "P38: a hard-coded provider switch in the production template is caught" "AICC_MAIL_PROVIDER must not be defined in the template"
fresh; sed -i.bak "s#^// ---- end P38 Brevo ----#// api.brevo.com\n// ---- end P38 Brevo ----#" "$TMP/w/infra/provision/wp-config.production.template.php"; neg "P38: the Brevo API host named in the template is caught" 'must never name the Brevo API host'
fresh; sed -i.bak "s#^// @@BREVO_END@@#// @@BREVO_END_X@@#" "$TMP/w/infra/provision/wp-config.production.template.php"; neg "P38: a malformed Brevo region is caught" 'exactly one P38 Brevo region'
fresh; sed -i.bak "s#'stage.copilt.org' );#'stage.copilt.org' ); // BREVO#" "$TMP/w/infra/provision/wp-config.stage.template.php"; neg "P38: a Brevo marker in the stage template is caught" 'stage template must carry no Brevo region'
fresh; sed -i.bak 's/check-brevo-key/check-brevo-x/g' "$TMP/w/infra/provision/render-wp-config.sh"; neg "P38: the renderer losing its key file shape check is caught" 'P38 gate lost: check-brevo-key'
fresh; sed -i.bak 's/a stage render may not carry the P38/a stage render may carry the P38/' "$TMP/w/infra/provision/render-wp-config.sh"; neg "P38: the renderer losing its staging refusal is caught" 'P38 gate lost: a stage render may not carry the P38'
fresh; printf '\nkeycopy="$(cat "$BKF")"\n' >> "$TMP/w/infra/provision/render-wp-config.sh"; neg "P38: a renderer that reads the key file into a shell variable is caught" 'must never read the Brevo key file into a shell variable'
fresh; sed -i.bak 's/xsmtpsib-/xsmtp-/g' "$TMP/w/infra/provision/host/aicc-set-brevo-key"; neg "P38: the host tool no longer refusing an SMTP key is caught" 'host key tool lost: xsmtpsib-'
fresh; sed -i.bak 's/os.replace(tmp, target)/os.rename(tmp, target)/' "$TMP/w/infra/provision/host/aicc-set-brevo-key"; neg "P38: a non-atomic key write is caught" 'host key tool lost: os.replace(tmp, target)'
fresh; sed -i.bak 's/must run as root/must be someone/' "$TMP/w/infra/provision/host/aicc-set-brevo-key"; neg "P38: the host tool without its non-root refusal is caught" 'host key tool lost: must run as root'
fresh; printf '\nset -x\n' >> "$TMP/w/infra/provision/host/aicc-set-brevo-key"; neg "P38: a host key tool that traces is caught" 'must never trace, fetch or eval'
fresh; sed -i.bak 's/O_NOFOLLOW/O_RDONLY/' "$TMP/w/infra/provision/host/aicc-set-brevo-key"; neg "P38: a host key tool that follows symlinks is caught" 'must refuse symlinks and special files'
fresh; sed -i.bak 's/read -rs/read -r/g' "$TMP/w/infra/provision/set-brevo-key.sh"; neg "P38: an owner script with a visible key prompt is caught" 'owner script lost: read -rs'
fresh; sed -i.bak 's/unset HISTFILE/true/' "$TMP/w/infra/provision/set-brevo-key.sh"; neg "P38: an owner script that keeps a history file is caught" 'owner script lost: unset HISTFILE'
fresh; sed -i.bak 's/StrictHostKeyChecking=yes/StrictHostKeyChecking=no/' "$TMP/w/infra/provision/set-brevo-key.sh"; neg "P38: an owner script without the pinned host key is caught" 'owner script lost: StrictHostKeyChecking=yes'
fresh; sed -i.bak 's/HOSTIP="157.230.110.211"/HOSTIP="203.0.113.9"/' "$TMP/w/infra/provision/set-brevo-key.sh"; neg "P38: an owner script aimed at another address is caught" 'owner script lost: HOSTIP='
fresh; sed -i.bak 's/3e897286ce82e55f4d866acf0d526a5f/00000000000000000000000000000000/' "$TMP/w/infra/provision/set-brevo-key.sh"; neg "P38: an owner script without the production stage id is caught" 'owner script lost: STAGE_ID='
fresh; printf '\nrssh "echo $k1"\n' >> "$TMP/w/infra/provision/set-brevo-key.sh"; neg "P38: an owner script that puts the key into a command line is caught" 'key variable must never be an argument'
fresh; printf '\nset -x\n' >> "$TMP/w/infra/provision/set-brevo-key.sh"; neg "P38: an owner script that traces is caught" 'owner script must never trace'
fresh; sed -i.bak 's#^  install_file "$INFRA/provision/host/aicc-set-brevo-key"#  true "$INFRA/provision/host/aicc-set-x"#' "$TMP/w/infra/provision/install-stack.sh"; neg "P38: an installer that no longer installs the Brevo key tool is caught" 'must install the Brevo key tool'
t_summary
